-- Master Catalog Schema Upgrade
alter table products add column default_selling_price decimal(12,2) default 0.00;
alter table products add column purchase_price decimal(12,2) default 0.00;
alter table products add column mrp decimal(12,2) default 0.00;
alter table products add column gst_percentage decimal(5,2) default 0.00;

-- Price History Audit Tracking table
create table if not exists product_price_history (
    id binary(16) primary key,
    product_id binary(16) not null,
    old_selling_price decimal(12,2) not null,
    new_selling_price decimal(12,2) not null,
    changed_at timestamp(6) not null,
    constraint fk_price_history_product foreign key (product_id) references products(id)
);

